const now = new Date();

const monthNamesUpper = ['JANUARY','FEBRUARY','MARCH','APRIL','MAY','JUNE','JULY','AUGUST','SEPTEMBER','OCTOBER','NOVEMBER','DECEMBER'];
const monthNamesTitle = ['January','February','March','April','May','June','July','August','September','October','November','December'];

const day = now.getDate();
const year = now.getFullYear();
const monthIndex = now.getMonth();
const monthUpper = monthNamesUpper[monthIndex];
const monthTitle = monthNamesTitle[monthIndex];

const directPdfUrl = `https://www.rbz.co.zw/documents/Exchange_Rates/${year}/${monthTitle}/RATES_${day}_${monthUpper}_${year}.pdf`;
// Month archive page slug — the numeric prefix (e.g. 1644-) changes per month/year on the live site.
// This is a best-effort guess; confirm the current slug by visiting the exchange rates page
// and update the pattern below, or replace with a lookup step if RBZ changes their URL scheme.

return [{
  json: {
    day,
    year,
    monthUpper,
    monthTitle,
    directPdfUrl,
    todayLabel: `${day} ${monthTitle} ${year}`
  }
}];

const text = $json.text || '';
const dateInfo = $('Build Date Info').item.json;

const lines = text.split('\n').map(l => l.trim()).filter(Boolean);

const rowPattern = /^([A-Z]{2,5}(?:\/[A-Z]{2,5})?)\s*(\*)?\s+([\d,]+\.?\d*)\s+([\d,]+\.?\d*)\s+([\d,]+\.?\d*)\s+([\d,]+\.?\d*)\s+([\d,]+\.?\d*)\s+([\d,]+\.?\d*)\s*$/;

const num = (s) => parseFloat(s.replace(/,/g, ''));

const results = [];
for (const line of lines) {
  const m = line.match(rowPattern);
  if (m) {
    results.push({
      json: {
        rate_date: `${dateInfo.year}-${String(new Date(`${dateInfo.monthTitle} ${dateInfo.day}, ${dateInfo.year}`).getMonth() + 1).padStart(2, '0')}-${String(dateInfo.day).padStart(2, '0')}`,
        currency: m[1],
        indicative: !!m[2],
        indices_bid: num(m[3]),
        indices_ask: num(m[4]),
        indices_mid: num(m[5]),
        rate_bid_zwg: num(m[6]),
        rate_ask_zwg: num(m[7]),
        rate_mid_zwg: num(m[8])
      }
    });
  }
}

return results;
